1	// 首页“创建公开房间”中“游戏规则 ↔ 人数上限”联动的界面回归测试。
2	//
3	// 与 ui.test.mjs 的分工：ui.test.mjs 覆盖成功/失败、列表刷新与名称整理；
4	// 本文件只盯住规则切换与人数上限的联动，把“切换过程 → 页面当前选择 →
5	// 实际提交的请求体 → 创建结果 → 房间列表”串起来断言，防止出现页面显示的是
6	// 当前规则下的人数，保存的却是先前规则下残留值的错配。
7	//
8	// 覆盖的产品行为（保持现有公开入口与产品行为不变）：
9	//   - 未选规则时人数不可填写，选项提示先选择游戏规则；
10	//   - 选五子棋后人数自动固定为 2，不能沿用先前飞行棋的 3/4；
11	//   - 选飞行棋后允许 2/3/4；从未选规则首次选飞行棋时人数保持未选择；
12	//     从五子棋切过去时当前合法的 2 人保留；
13	//   - 来回切换以当前选择为准（飞行棋 4 → 五子棋 2 → 飞行棋仍为 2）；
14	//   - 切换规则时名称与每步时间限制保留，仅人数随规则调整；
15	//   - 切回“请选择游戏规则”后人数重新不可填写，旧人数不再是可提交的值；
16	//   - 规则为空或首次选飞行棋未选人数时提交，页面明确指出缺哪项：
17	//     不发创建请求、不新增房间、已填内容保留；补齐后按此时的规则/人数创建；
18	//   - 创建成功后人数回到不可填写的初始状态；飞行棋的 3 人与 4 人都必须按
19	//     所选值创建（请求体、创建结果、列表三处一致），不能都存成 2。
20	//
21	// 运行：npm test（需要系统 Chrome，可用 CHROME_PATH 指定路径）。
22	
23	import { test, before, after } from 'node:test';
24	import assert from 'node:assert/strict';
25	import { execFile, spawn } from 'node:child_process';
26	import { mkdtemp, writeFile, rm } from 'node:fs/promises';
27	import { tmpdir } from 'node:os';
28	import path from 'node:path';
29	import { promisify } from 'node:util';
30	import puppeteer from 'puppeteer-core';
31	
32	const repoRoot = import.meta.dirname;
33	const chromePath = process.env.CHROME_PATH || '/usr/bin/google-chrome';
34	
35	let serverBin;
36	let browser;
37	
38	// 与 ui.test.mjs 相同的种子记录：验证联动用例创建房间时，
39	// 原有房间的内容与次序保持不变、新房间按原方式追加。
40	const SEED_ALPHA =
41	  '{"id":"seed-alpha","name":"晨间飞行棋","game":"ludo","capacity":4,"turnSeconds":30,' +
42	  '"status":"playing","visibility":"public","createdAt":"2026-01-01T08:00:00Z","note":"保留我","tags":["老友","周赛"]}';
43	const SEED_BETA =
44	  '{"id":"seed-beta","name":"午夜五子棋","game":"gomoku","capacity":2,"turnSeconds":0,' +
45	  '"status":"waiting","visibility":"public","createdAt":"2026-01-02T23:00:00Z","extra":{"rank":3}}';
46	
47	before(async () => {
48	  const dir = await mkdtemp(path.join(tmpdir(), 'score-arena-uibin-'));
49	  serverBin = path.join(dir, 'score-arena');
50	  await promisify(execFile)('go', ['build', '-o', serverBin, '.'], { cwd: repoRoot });
51	  browser = await puppeteer.launch({
52	    executablePath: chromePath,
53	    headless: true,
54	    args: ['--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage'],
55	  });
56	});
57	
58	after(async () => {
59	  if (browser) await browser.close();
60	  if (serverBin) await rm(path.dirname(serverBin), { recursive: true, force: true });
61	});
62	
63	function startServer(t, dataDir) {
64	  const proc = spawn(
65	    serverBin,
66	    ['serve', '--host', '127.0.0.1', '--port', '0', '--data-dir', dataDir],
67	    { stdio: ['ignore', 'pipe', 'inherit'] },
68	  );
69	  t.after(() => { proc.kill('SIGKILL'); });
70	  return new Promise((resolve, reject) => {
71	    let buf = '';
72	    const timer = setTimeout(() => reject(new Error('等待服务监听地址超时')), 15000);
73	    proc.stdout.on('data', (chunk) => {
74	      buf += chunk.toString();
75	      const m = buf.match(/listening on (http:\/\/\S+)/);
76	      if (m) {
77	        clearTimeout(timer);
78	        resolve(m[1]);
79	      }
80	    });
81	    proc.on('exit', (code) => {
82	      clearTimeout(timer);
83	      reject(new Error(`服务在输出监听地址前退出，退出码 ${code}`));
84	    });
85	  });
86	}
87	
88	async function seedRooms(dataDir, ...records) {
89	  await writeFile(path.join(dataDir, 'rooms.json'), '[\n' + records.join(',\n') + '\n]\n');
90	}
91	
92	async function setupPage(t) {
93	  const dataDir = await mkdtemp(path.join(tmpdir(), 'score-arena-uidata-'));
94	  t.after(() => rm(dataDir, { recursive: true, force: true }));
95	  await seedRooms(dataDir, SEED_ALPHA, SEED_BETA);
96	  const baseURL = await startServer(t, dataDir);
97	  const page = await browser.newPage();
98	  t.after(() => page.close());
99	  await page.goto(baseURL, { waitUntil: 'load' });
100	  await waitForRowCount(page, 2);
101	  return { page, baseURL };
102	}
103	
104	function waitForRowCount(page, n) {
105	  return page.waitForFunction(
106	    (want) => document.querySelectorAll('#list-area table tbody tr').length === want,
107	    { timeout: 10000 },
108	    n,
109	  );
110	}
111	
112	function waitForMessageKind(page, kind) {
113	  return page.waitForFunction(
114	    (cls) => document.getElementById('form-msg').classList.contains(cls),
115	    { timeout: 10000 },
116	    kind,
117	  );
118	}
119	
120	// readCapacity 读取人数上限下拉的完整状态：是否禁用、当前值、可选项的值与文案、
121	// 首项（占位项）文案。联动断言必须同时看“当前值”和“可选项集合”，
122	// 因为残留值可能既显示不出来又仍被提交。
123	function readCapacity(page) {
124	  return page.$eval('#capacity', (sel) => ({
125	    disabled: sel.disabled,
126	    value: sel.value,
127	    options: [...sel.options].map((o) => ({ value: o.value, text: o.textContent })),
128	    optionValues: [...sel.options].map((o) => o.value),
129	    placeholder: sel.options[0] ? sel.options[0].textContent : null,
130	  }));
131	}
132	
133	function readFormState(page) {
134	  return page.evaluate(() => ({
135	    name: document.getElementById('name').value,
136	    game: document.getElementById('game').value,
137	    capacity: document.getElementById('capacity').value,
138	    capacityDisabled: document.getElementById('capacity').disabled,
139	    turnSeconds: document.getElementById('turnSeconds').value,
140	    submitDisabled: document.getElementById('submit').disabled,
141	  }));
142	}
143	
144	function readMessage(page) {
145	  return page.evaluate(() => {
146	    const el = document.getElementById('form-msg');
147	    return { className: el.className, text: el.textContent };
148	  });
149	}
150	
151	function readRows(page) {
152	  return page.$$eval('#list-area table tbody tr', (trs) =>
153	    trs.map((tr) => [...tr.querySelectorAll('td')].map((td) => td.textContent)),
154	  );
155	}
156	
157	async function readServerRooms(baseURL) {
158	  const res = await fetch(baseURL + '/api/rooms');
159	  assert.equal(res.status, 200);
160	  return (await res.json()).rooms;
161	}
162	
163	// trackRoomPosts 记录页面发出的每一次创建请求体：联动用例据此确认
164	// 提交给服务的规则/人数就是页面当前显示的选择，且被页面拦截时没有请求发出。
165	function trackRoomPosts(page) {
166	  const bodies = [];
167	  page.on('request', (req) => {
168	    if (req.method() === 'POST' && req.url().endsWith('/api/rooms')) {
169	      bodies.push(req.postData());
170	    }
171	  });
172	  return bodies;
173	}
174	
175	function nextCreated(page) {
176	  return new Promise((resolve, reject) => {
177	    page.on('response', (resp) => {
178	      if (resp.request().method() === 'POST' && resp.url().endsWith('/api/rooms')) {
179	        resp.json().then(resolve, reject);
180	      }
181	    });
182	  });
183	}
184	
185	// 模拟用户在规则下拉上的一次真实选择（会触发 change 事件）。
186	async function chooseGame(page, value) {
187	  await page.select('#game', value);
188	}
189	
190	// 切换规则后等待人数下拉完成重建：禁用态与给定期望值一致。
191	async function waitForCapacityValue(page, value) {
192	  await page.waitForFunction(
193	    (want) => {
194	      const sel = document.getElementById('capacity');
195	      return want === null ? sel.disabled : (!sel.disabled && sel.value === want);
196	    },
197	    { timeout: 5000 },
198	    value,
199	  );
200	}
201	
202	// 等待人数下拉启用且可选项集合与期望一致；切换后保留的当前值可能不是空，
203	// （五子棋切到飞行棋时保留 2），因此用可选项集合而非当前值判断重建完成。
204	async function waitForCapacityOptions(page, values) {
205	  await page.waitForFunction(
206	    (want) => {
207	      const sel = document.getElementById('capacity');
208	      return !sel.disabled &&
209	        [...sel.options].map((o) => o.value).join(',') === want.join(',');
210	    },
211	    { timeout: 5000 },
212	    values,
213	  );
214	}
215	
216	const SUCCESS_PREFIX = '房间已创建，编号：';
217	
218	// 初始状态：规则未选择时人数上限不可填写，选项明确提示先选择游戏规则，
219	// 当前值为空。
220	test('未选择规则时人数上限不可填写，提示先选择游戏规则', { timeout: 60000 }, async (t) => {
221	  const { page } = await setupPage(t);
222	
223	  assert.equal(await page.$eval('#game', (el) => el.value), '');
224	  const cap = await readCapacity(page);
225	  assert.equal(cap.disabled, true, '未选规则时人数下拉应禁用');
226	  assert.equal(cap.value, '', '未选规则时人数当前值应为空');
227	  assert.deepEqual(cap.optionValues, [''], '禁用状态下只应有一个占位选项');
228	  assert.equal(cap.placeholder, '请先选择游戏规则', '占位项应提示先选择游戏规则');
229	});
230	
231	// 选择五子棋：人数自动成为 2 人（占位项 + 唯一合法值 2），无需也无法选择
232	// 3/4；从飞行棋 3 人切过来时不能沿用 3。
233	test('选择五子棋后人数自动固定为 2，不能沿用此前飞行棋的 3 或 4', { timeout: 60000 }, async (t) => {
234	  const { page } = await setupPage(t);
235	
236	  // 先选飞行棋并选 3 人，制造“先前规则下的值”。
237	  await chooseGame(page, 'ludo');
238	  await waitForCapacityValue(page, '');
239	  await page.select('#capacity', '3');
240	  assert.equal((await readCapacity(page)).value, '3');
241	
242	  // 切到五子棋：人数自动变为 2，可选项中不存在 3/4，旧值 3 被清除。
243	  await chooseGame(page, 'gomoku');
244	  await waitForCapacityValue(page, '2');
245	  let cap = await readCapacity(page);
246	  assert.equal(cap.disabled, false);
247	  assert.deepEqual(cap.optionValues, ['', '2'], '五子棋应只有固定 2 人这一个可选值');
248	  assert.equal(cap.value, '2', '切到五子棋后必须自动成为 2 人，不能沿用 3');
249	
250	  // 再来一次：飞行棋选 4 后切五子棋，同样必须归 2。
251	  await chooseGame(page, 'ludo');
252	  await waitForCapacityOptions(page, ['', '2', '3', '4']);
253	  assert.equal((await readCapacity(page)).value, '2', '五子棋切到飞行棋应保留当前的 2 人');
254	  await page.select('#capacity', '4');
255	  assert.equal((await readCapacity(page)).value, '4');
256	  await chooseGame(page, 'gomoku');
257	  await waitForCapacityValue(page, '2');
258	  cap = await readCapacity(page);
259	  assert.equal(cap.value, '2', '切到五子棋后必须自动成为 2 人，不能沿用 4');
260	  assert.deepEqual(cap.optionValues, ['', '2']);
261	});
262	
263	// 选择飞行棋：允许 2/3/4，且必须有一个空占位项表示未选择。
264	test('选择飞行棋后可选择 2、3、4 人', { timeout: 60000 }, async (t) => {
265	  const { page } = await setupPage(t);
266	
267	  await chooseGame(page, 'ludo');
268	  await waitForCapacityValue(page, '');
269	  const cap = await readCapacity(page);
270	  assert.equal(cap.disabled, false, '选飞行棋后人数下拉应可填写');
271	  assert.deepEqual(cap.optionValues, ['', '2', '3', '4'], '飞行棋应提供未选择占位与 2/3/4 人');
272	  assert.equal(cap.placeholder, '请选择人数上限…');
273	
274	  // 三个合法值都能被用户选中。
275	  for (const n of ['2', '3', '4']) {
276	    await page.select('#capacity', n);
277	    assert.equal((await readCapacity(page)).value, n);
278	  }
279	});
280	
281	// 从未选规则的初始状态首次选择飞行棋：人数保持未选择，页面不替用户决定。
282	test('首次选择飞行棋时人数保持未选择，不替用户决定', { timeout: 60000 }, async (t) => {
283	  const { page } = await setupPage(t);
284	
285	  await chooseGame(page, 'ludo');
286	  await waitForCapacityValue(page, '');
287	  const cap = await readCapacity(page);
288	  assert.equal(cap.disabled, false);
289	  assert.equal(cap.value, '', '首次选飞行棋不应自动选中任何人数');
290	});
291	
292	// 从五子棋切到飞行棋：五子棋当前合法的 2 人应保留，而不是清空或跳成 3/4。
293	test('从五子棋切到飞行棋时保留当前合法的 2 人', { timeout: 60000 }, async (t) => {
294	  const { page } = await setupPage(t);
295	
296	  await chooseGame(page, 'gomoku');
297	  await waitForCapacityValue(page, '2');
298	  await chooseGame(page, 'ludo');
299	  await waitForCapacityValue(page, '2');
300	  const cap = await readCapacity(page);
301	  assert.deepEqual(cap.optionValues, ['', '2', '3', '4']);
302	  assert.equal(cap.value, '2', '从五子棋切到飞行棋应保留合法的 2 人');
303	});
304	
305	// 规则来回切换以当前选择为准：飞行棋选 4 → 改选五子棋必须是 2 →
306	// 再切回飞行棋仍保留 2，不能“记住”最初的 4 人。
307	test('来回切换以当前选择为准：飞行棋 4 → 五子棋 2 → 飞行棋保留 2', { timeout: 60000 }, async (t) => {
308	  const { page } = await setupPage(t);
309	
310	  await chooseGame(page, 'ludo');
311	  await waitForCapacityValue(page, '');
312	  await page.select('#capacity', '4');
313	  assert.equal((await readCapacity(page)).value, '4');
314	
315	  await chooseGame(page, 'gomoku');
316	  await waitForCapacityValue(page, '2');
317	  assert.equal((await readCapacity(page)).value, '2', '改选五子棋后人数必须是 2');
318	
319	  await chooseGame(page, 'ludo');
320	  await waitForCapacityValue(page, '2');
321	  assert.equal((await readCapacity(page)).value, '2', '再切回飞行棋应保留当前的 2 人，不能恢复最初的 4 人');
322	
323	  // 再多切一轮确认 4 不会在后续切换中复活。
324	  await chooseGame(page, 'gomoku');
325	  await waitForCapacityValue(page, '2');
326	  await chooseGame(page, 'ludo');
327	  await waitForCapacityValue(page, '2');
328	  assert.equal((await readCapacity(page)).value, '2');
329	});
330	
331	// 切换规则时，已填写的房间名称与每步时间限制必须原样保留，仅人数随规则调整。
332	test('切换规则后名称与时间限制保留，仅人数随规则调整', { timeout: 60000 }, async (t) => {
333	  const { page } = await setupPage(t);
334	
335	  const name = '  规则来回切的房间  ';
336	  await page.type('#name', name);
337	  await page.type('#turnSeconds', '45');
338	
339	  // 五子棋（自动 2 人）→ 飞行棋（2 人合法，保留）→ 选 4 → 五子棋（归 2）。
340	  await chooseGame(page, 'gomoku');
341	  await waitForCapacityValue(page, '2');
342	  await chooseGame(page, 'ludo');
343	  await waitForCapacityOptions(page, ['', '2', '3', '4']);
344	  assert.equal((await readCapacity(page)).value, '2', '五子棋切到飞行棋应保留合法的 2 人');
345	  await page.select('#capacity', '4');
346	  await chooseGame(page, 'gomoku');
347	  await waitForCapacityValue(page, '2');
348	
349	  const form = await readFormState(page);
350	  assert.equal(form.name, name, '切换规则后名称输入应原样保留（含首尾空白）');
351	  assert.equal(form.turnSeconds, '45', '切换规则后时间限制应保留');
352	  assert.equal(form.game, 'gomoku');
353	  assert.equal(form.capacity, '2', '仅人数应随规则调整为五子棋的 2 人');
354	  assert.equal(form.capacityDisabled, false);
355	});
356	
357	// 切回“请选择游戏规则”：人数重新不可填写、旧人数不再是可提交的选择；
358	// 名称与时间仍保留。
359	test('切回未选择规则后人数重新禁用，旧人数不可提交，名称与时间保留', { timeout: 60000 }, async (t) => {
360	  const { page } = await setupPage(t);
361	
362	  const name = '又不想选规则了';
363	  await page.type('#name', name);
364	
365	  // 飞行棋选 4，再切到五子棋（2），再清空规则：旧的 2 必须随之失效。
366	  await chooseGame(page, 'ludo');
367	  await waitForCapacityValue(page, '');
368	  await page.select('#capacity', '4');
369	  await chooseGame(page, 'gomoku');
370	  await waitForCapacityValue(page, '2');
371	  await page.type('#turnSeconds', '60');
372	  await chooseGame(page, '');
373	  await waitForCapacityValue(page, null);
374	
375	  const cap = await readCapacity(page);
376	  assert.equal(cap.disabled, true, '规则清空后人数下拉应重新禁用');
377	  assert.equal(cap.value, '', '旧人数不应再作为当前值');
378	  assert.deepEqual(cap.optionValues, [''], '禁用后只剩占位项，2/3/4 均不可提交');
379	  assert.equal(cap.placeholder, '请先选择游戏规则');
380	
381	  const form = await readFormState(page);
382	  assert.equal(form.game, '');
383	  assert.equal(form.capacity, '');
384	  assert.equal(form.capacityDisabled, true);
385	  assert.equal(form.name, name, '名称应保留');
386	  assert.equal(form.turnSeconds, '60', '时间限制应保留');
387	});
388	
389	// 规则为空时提交：页面明确提示缺少游戏规则，不发创建请求、不新增房间，
390	// 已填内容保留。
391	test('规则为空提交被页面拦截：明确提示缺少规则，不发请求、不增房间、内容保留', { timeout: 60000 }, async (t) => {
392	  const { page, baseURL } = await setupPage(t);
393	  const postBodies = trackRoomPosts(page);
394	  const initialRows = await readRows(page);
395	
396	  // 先选过五子棋再切回空规则，制造“人数下拉里曾经有值”的状态，
397	  // 确认旧值不会被偷偷提交。
398	  await chooseGame(page, 'gomoku');
399	  await waitForCapacityValue(page, '2');
400	  await chooseGame(page, '');
401	  await waitForCapacityValue(page, null);
402	
403	  await page.type('#name', '缺规则的房间');
404	  await page.type('#turnSeconds', '30');
405	  await page.click('#submit');
406	
407	  await waitForMessageKind(page, 'error');
408	  const msg = await readMessage(page);
409	  assert.equal(msg.text, '请选择游戏规则。', '应明确提示缺少游戏规则');
410	  assert.ok(!msg.className.includes('ok'));
411	
412	  await new Promise((resolve) => setTimeout(resolve, 300));
413	  assert.equal(postBodies.length, 0, '页面拦截时不应发出创建请求');
414	  assert.equal((await readServerRooms(baseURL)).length, 2, '服务端不应新增房间');
415	  assert.deepEqual(await readRows(page), initialRows, '列表应保持不变');
416	
417	  const form = await readFormState(page);
418	  assert.equal(form.name, '缺规则的房间', '已填名称应保留');
419	  assert.equal(form.game, '', '规则仍为空，等用户选择');
420	  assert.equal(form.capacity, '');
421	  assert.equal(form.capacityDisabled, true, '人数仍不可填写');
422	  assert.equal(form.turnSeconds, '30', '已填时间应保留');
423	  assert.equal(form.submitDisabled, false);
424	});
425	
426	// 首次选择飞行棋但未选人数时提交：明确提示缺少人数上限，不发请求、
427	// 不增房间，已填内容（含已选规则）保留。
428	test('首次选飞行棋未选人数提交被拦截：提示缺少人数，不发请求、内容保留', { timeout: 60000 }, async (t) => {
