482	  const created = await createdPromise;
483	  assert.equal(postBodies.length, 1, '拦截时不发请求，补齐后只发出一次创建请求');
484	  assert.deepEqual(JSON.parse(postBodies[0]), {
485	    name: '补齐人数的房间',
