520	  }, '成功后表单应复位，人数重新不可填写');
521	  assert.equal((await readServerRooms(baseURL)).length, 3);
522	});
523	
524	// 切换过程与最终提交的端到端一致性：飞行棋选 4 → 五子棋（自动 2）→
525	// 飞行棋（保留 2），最终以飞行棋 2 人提交；请求体、创建结果、列表三处一致。
526	test('端到端：多轮切换后最终以飞行棋 2 人创建，三处值一致', { timeout: 60000 }, async (t) => {
527	  const { page, baseURL } = await setupPage(t);
528	  const postBodies = trackRoomPosts(page);
529	  const initialRows = await readRows(page);
530	
531	  await page.type('#name', '  最终是飞行棋两人  ');
532	  await page.type('#turnSeconds', '0');
533	
534	  await chooseGame(page, 'ludo');
535	  await waitForCapacityValue(page, '');
536	  await page.select('#capacity', '4'); // 最初选过 4
537	  await chooseGame(page, 'gomoku');
538	  await waitForCapacityValue(page, '2');
539	  await chooseGame(page, 'ludo');
540	  await waitForCapacityValue(page, '2'); // 回到飞行棋后应保留 2，而非 4
541	
542	  assert.equal((await readFormState(page)).capacity, '2', '提交前页面显示的人数必须是 2');
543	
544	  const createdPromise = nextCreated(page);
545	  await page.click('#submit');
546	  await waitForMessageKind(page, 'ok');
547	  const created = await createdPromise;
548	
549	  assert.equal(postBodies.length, 1);
550	  assert.deepEqual(JSON.parse(postBodies[0]), {
551	    name: '  最终是飞行棋两人  ',
552	    game: 'ludo',
553	    capacity: 2,
554	    turnSeconds: 0,
555	  }, '请求体必须与最终选择一致，不能携带最初的 4');
556	
557	  assert.equal(created.game, 'ludo');
558	  assert.equal(created.capacity, 2);
559	  assert.equal(created.turnSeconds, 0);
560	
561	  await waitForRowCount(page, 3);
562	  const rows = await readRows(page);
563	  assert.deepEqual(rows.slice(0, 2), initialRows, '原有房间的内容或次序被改变');
564	  assert.deepEqual(rows[2].slice(0, 5), [
565	    created.id, '最终是飞行棋两人', '飞行棋', '2 人', '不限时',
566	  ], '列表的规则与人数必须与最终选择一致');
567	  assert.equal((await readServerRooms(baseURL))[2].capacity, 2);
568	});
569	
570	// 飞行棋 4 人独立成功路径：确保 4 这个值本身能贯穿页面、请求体、服务端保存
571	// 与列表（与 3 人用例一起防止“飞行棋都被存成 2”的回归）。
572	test('端到端：飞行棋选择 4 人时按 4 创建，请求体/创建结果/列表一致', { timeout: 60000 }, async (t) => {
573	  const { page, baseURL } = await setupPage(t);
574	  const postBodies = trackRoomPosts(page);
