444	  assert.ok(msg.text.startsWith(SUCCESS_PREFIX), `应保留创建成功提示，实际: ${msg.text}`);
445	  assert.equal(msg.text.slice(SUCCESS_PREFIX.length), created.id, '提示编号应与创建结果一致');
446	  assert.ok(!msg.text.includes(CONN_FAILURE_TEXT), '已确认成功的创建不应显示连接失败提示');
447	
448	  // 表单仍按成功处理（恢复初始填写状态）。
449	  assert.deepEqual(await readFormState(page), RESET_FORM, '列表刷新连接失败不应影响已成功创建的表单处理');
450	
451	  // 列表区域明确显示加载失败，而不是空列表提示或旧内容。
452	  await page.waitForFunction(
453	    () => !!document.querySelector('#list-area .list-error'),
454	    { timeout: 10000 },
455	  );
456	  const list = await readListArea(page);
457	  assert.equal(list.errorText, LIST_ERROR_TEXT);
458	  assert.equal(list.emptyText, null, '列表刷新连接失败时不得显示“还没有房间记录”');
459	  assert.ok(!list.hasTable, '列表刷新连接失败时不应展示旧表格冒充最新列表');
460	
461	  // 列表读取连接失败落定后，成功提示与编号仍然保留，未被改写成创建失败。
462	  const msgAfter = await readMessage(page);
463	  assert.ok(msgAfter.className.includes('ok'), '列表刷新连接失败不应把已完成的创建说成失败');
464	  assert.equal(msgAfter.text, msg.text, '成功提示与编号应保留');
465	  assert.equal((await readFormState(page)).submitDisabled, false, '本次操作完成后创建按钮应恢复可用');
466	
467	  // 服务端确实已保存本次创建（证明创建本身成功，只是刷新连接失败）。
468	  const serverRooms = await readServerRooms(baseURL);
469	  assert.equal(serverRooms.length, 3, '服务端应已保存新房间');
470	  assert.equal(serverRooms[2].id, created.id, '服务端保存的编号应与页面提示一致');
471	});
