function submit(payload, submittedRaw) {
  submitBtn.disabled = true;
  fetch('/api/rooms', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload)
  }).then(function (resp) {
    return resp.json().catch(function () { return {}; }).then(function (data) {
      return { ok: resp.ok, status: resp.status, data: data };
    });
  }).then(function (result) {
    if (result.ok && result.status === 201) {
      // 提交后表单始终保持可编辑，本次房间只按点击时的 payload 创建；
      // 等待响应期间用户可以继续填写下一间房，这些输入既不改变已提交的
      // 配置，也不会自动再发出一次创建。成功返回时逐字比较四项当前填写值
      // 与提交时快照：完全一致才恢复初始表单；任一项不同（哪怕只改过
      // 首尾空白，或改完又恢复到别的值）就整体保留当前四项内容及对应的
      // 人数选择状态，绝不只保留改过的单项，也不把其他项恢复成旧配置。
      var currentRaw = {
        name: nameInput.value,
        game: gameSel.value,
        capacity: capSel.value,
        turnSeconds: turnInput.value
      };
      var unchanged = currentRaw.name === submittedRaw.name &&
        currentRaw.game === submittedRaw.game &&
        currentRaw.capacity === submittedRaw.capacity &&
        currentRaw.turnSeconds === submittedRaw.turnSeconds;
      if (unchanged) {
        showMessage('ok', '房间已创建，编号：' + result.data.id);
        form.reset();
        syncCapacity();
      } else {
        // 保留下来的只是未提交的填写内容（可能还没填完整），不能被当成
        // 刚创建的房间；明确提示用户需要时可直接再次提交。
        showMessage('ok', '房间已创建，编号：' + result.data.id +
          '。表单中当前填写的内容尚未提交，需要再创建一间时可直接点击“创建房间”。');
      }
      return loadRooms();
    }
    // 创建失败：保留当时最新的填写内容（不回退到提交前的值），仅显示原因。
    var reason = result.data && result.data.error ? result.data.error
               : ('创建失败（HTTP ' + result.status + '）');
    showMessage('error', reason);
  }).catch(function () {
    showMessage('error', '无法连接服务，请确认服务仍在运行后重试。');
  }).finally(function () {
    submitBtn.disabled = false;
  });
}

