import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { execFile, spawn } from 'node:child_process';
import { mkdtemp, writeFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { promisify } from 'node:util';
import puppeteer from '/opt/gsb-production/workspaces/coco/prod-17/A/task029/node_modules/puppeteer-core/lib/esm/puppeteer/puppeteer-core.js';

const repoRoot = '/opt/gsb-production/workspaces/coco/prod-17/A/task029';
let serverBin, browser;
const SEED = '{"id":"seed-alpha","name":"晨间飞行棋","game":"ludo","capacity":4,"turnSeconds":30,"status":"playing","visibility":"public","createdAt":"2026-01-01T08:00:00Z"}';

before(async () => {
  const dir = await mkdtemp(path.join(tmpdir(), 'sv-'));
  serverBin = path.join(dir, 'score-arena');
  await promisify(execFile)('go', ['build', '-o', serverBin, '.'], { cwd: repoRoot });
  browser = await puppeteer.launch({ executablePath: '/usr/bin/google-chrome', headless: true, args: ['--no-sandbox'] });
});
after(async () => { await browser?.close(); });

function startServer(t, dataDir) {
  const proc = spawn(serverBin, ['serve','--host','127.0.0.1','--port','0','--data-dir',dataDir], { stdio:['ignore','pipe','inherit'] });
  t.after(() => proc.kill('SIGKILL'));
  return new Promise((resolve, reject) => {
    let buf='';
    const timer=setTimeout(()=>reject(new Error('timeout')),15000);
    proc.stdout.on('data', c => { buf+=c; const m=buf.match(/listening on (http:\/\/\S+)/); if(m){clearTimeout(timer);resolve(m[1]);} });
  });
}
const readForm = (page) => page.evaluate(() => ({
  name: document.getElementById('name').value, game: document.getElementById('game').value,
  capacity: document.getElementById('capacity').value,
  capacityDisabled: document.getElementById('capacity').disabled,
  turnSeconds: document.getElementById('turnSeconds').value,
  submitDisabled: document.getElementById('submit').disabled,
}));
const readMsg = (page) => page.$eval('#form-msg', el => ({ cls: el.className, text: el.textContent }));

async function setup(t) {
  const dataDir = await mkdtemp(path.join(tmpdir(),'sd-'));
  t.after(() => rm(dataDir,{recursive:true,force:true}));
  await writeFile(path.join(dataDir,'rooms.json'),'[\n'+SEED+'\n]\n');
  const baseURL = await startServer(t, dataDir);
  const page = await browser.newPage();
  t.after(() => page.close());
  await page.goto(baseURL, { waitUntil: 'load' });
  await page.waitForFunction(() => document.querySelectorAll('#list-area table tbody tr').length === 1);
  return { page, baseURL };
}

// 场景1：提交五子棋2人0秒，等待期间改成飞行棋4人60秒；服务保存五子棋，表单保留飞行棋配置
test('等待期间修改：服务保存原提交，表单保留新填写，且可再次提交保留配置', { timeout: 60000 }, async (t) => {
  const { page, baseURL } = await setup(t);
  const posts = [];
  let releasePost;
  const held = new Promise(r => releasePost = r);
  await page.setRequestInterception(true);
  page.on('request', req => {
    if (req.method()==='POST' && req.url().endsWith('/api/rooms')) { posts.push(req.postData()); held.then(()=>req.continue()); }
    else req.continue();
  });
  await page.type('#name','五子棋房间');
  await page.select('#game','gomoku');
  await page.waitForFunction(()=>document.getElementById('capacity').value==='2');
  await page.type('#turnSeconds','0');
  await page.click('#submit');
  await page.waitForFunction(()=>document.getElementById('submit').disabled);

  // 等待期间改为飞行棋 4 人 60 秒（名称也改）
  await page.$eval('#name', el => { el.value=''; });
  await page.type('#name','飞行棋房间');
  await page.select('#game','ludo');
  await page.waitForFunction(()=>!document.getElementById('capacity').disabled);
  await page.select('#capacity','4');
  await page.$eval('#turnSeconds', el => { el.value=''; });
  await page.type('#turnSeconds','60');
  assert.deepEqual(await readForm(page), {
    name:'飞行棋房间', game:'ludo', capacity:'4', capacityDisabled:false,
    turnSeconds:'60', submitDisabled:true,
  }, '等待期间表单保持可编辑且保留新输入');
  assert.equal(posts.length, 1);
  assert.deepEqual(JSON.parse(posts[0]), { name:'五子棋房间', game:'gomoku', capacity:2, turnSeconds:0 });

  releasePost();
  await page.waitForFunction(()=>!document.getElementById('submit').disabled);
  const msg = await readMsg(page);
  assert.ok(msg.cls.includes('ok'));
  assert.match(msg.text, /房间已创建，编号：/);
  assert.match(msg.text, /尚未提交/);

  // 表单完整保留新四项
  assert.deepEqual(await readForm(page), {
    name:'飞行棋房间', game:'ludo', capacity:'4', capacityDisabled:false,
    turnSeconds:'60', submitDisabled:false,
  });

  // 服务保存的是原五子棋
  const rooms = await (await fetch(baseURL+'/api/rooms')).json();
  assert.equal(rooms.rooms.length, 2);
  const created = rooms.rooms[1];
  assert.equal(created.game,'gomoku');
  assert.equal(created.capacity,2);
  assert.equal(created.turnSeconds,0);
  assert.ok(msg.text.includes(created.id));
  // 列表展示五子棋房间
  await page.waitForFunction(()=>document.querySelectorAll('#list-area table tbody tr').length===2);
  const rowText = await page.$eval('#list-area table tbody tr:last-child', tr=>tr.textContent);
  assert.ok(rowText.includes('五子棋'));
  assert.ok(!rowText.includes('飞行棋房间'));

  // 直接再提交保留的飞行棋配置
  const p2 = new Promise(res => page.on('response', r => { if(r.request().method()==='POST') r.json().then(res); }));
  await page.click('#submit');
  const created2 = await p2;
  assert.equal(created2.game,'ludo'); assert.equal(created2.capacity,4); assert.equal(created2.turnSeconds,60);
  const msg2 = await readMsg(page);
  // 第二次未在等待期间改动 → 复位
  assert.deepEqual(await readForm(page), { name:'',game:'',capacity:'',capacityDisabled:true,turnSeconds:'',submitDisabled:false });
  assert.ok(!/尚未提交/.test(msg2.text));
});

// 场景2：等待期间只改名称首尾空白 → 视为新输入，保留
test('只改首尾空白也算新输入，成功后保留', { timeout: 60000 }, async (t) => {
  const { page } = await setup(t);
