  assert.equal((await readForm(page)).name, '  测试房间  ');
});

// 场景3：提交时名称带空白、期间未动 → 正常复位
test('提交名称带空白且未改动 → 复位', { timeout: 60000 }, async (t) => {
  const { page } = await setup(t);
