// 场景4：等待期间改了又恢复全部原值 → 复位
test('改过又恢复全部值 → 按未改变处理', { timeout: 60000 }, async (t) => {
  const { page } = await setup(t);
  let releasePost; const held = new Promise(r=>releasePost=r);
