});

// 场景5：等待期间改成未填完整（规则切回空）→ 保留，不补齐不清空
test('等待期间改成未填完整 → 保留当前不完整内容', { timeout: 60000 }, async (t) => {
  const { page } = await setup(t);
  let releasePost; const held = new Promise(r=>releasePost=r);
  await page.setRequestInterception(true);
  page.on('request', req => {
    if (req.method()==='POST' && req.url().endsWith('/api/rooms')) held.then(()=>req.continue());
    else req.continue();
  });
  await page.type('#name','测试房间');
  await page.select('#game','gomoku');
  await page.waitForFunction(()=>document.getElementById('capacity').value==='2');
  await page.type('#turnSeconds','0');
  await page.click('#submit');
  await page.waitForFunction(()=>document.getElementById('submit').disabled);
  await page.select('#game','');
  releasePost();
  await page.waitForFunction(()=>!document.getElementById('submit').disabled);
  assert.deepEqual(await readForm(page), {
    name:'测试房间', game:'', capacity:'', capacityDisabled:true,
    turnSeconds:'0', submitDisabled:false,
  });
  // 再次提交时现有校验仍生效
  await page.click('#submit');
  assert.equal((await readMsg(page)).text, '请选择游戏规则。');
});
